// src/paginas/psicopedagogica/EvaluacionPsicoForm.jsx
import { useState, useEffect } from "react";
import api from "../../servicios/api";
import { listarEvaluacionesPsico } from "../../servicios/evaluacionPsico";

function EvaluacionPsicoForm({ evaluacion, onSuccess }) {
  const [formData, setFormData] = useState({
    estudiante: "",
    evaluador: "",
    fecha: "",
    observaciones: "",
  });

  const [alumnos, setAlumnos] = useState([]);
  const [alumnoSelected, setAlumnoSelected] = useState(null);

  // ===============================
  // CARGAR ALUMNOS
  // ===============================
  useEffect(() => {
    async function cargarAlumnos() {
      try {
        const res = await api.get("/estudiantes/");
        setAlumnos(res.data);
      } catch (error) {
        console.error("Error cargando alumnos:", error);
      }
    }
    cargarAlumnos();
  }, []);

  // ===============================
  // SI ESTAMOS EDITANDO
  // ===============================
  useEffect(() => {
    if (evaluacion) {
      setFormData({
        estudiante: evaluacion.estudiante || "",
        evaluador: evaluacion.evaluador || "",
        fecha: evaluacion.fecha || "",
        observaciones: evaluacion.observaciones || "",
      });

      // cargar alumno para ficha
      if (evaluacion.estudiante) {
        cargarFichaAlumno(evaluacion.estudiante);
      }
    }
  }, [evaluacion]);

  // ===============================
  // CARGAR FICHA DEL ALUMNO
  // ===============================
  async function cargarFichaAlumno(id) {
    try {
      const res = await api.get(`/estudiantes/${id}/`);
      setAlumnoSelected(res.data);
    } catch (error) {
      console.error("Error cargando ficha del alumno:", error);
    }
  }

  // ===============================
  // SUBMIT (Crear o Editar)
  // ===============================
  async function handleSubmit(e) {
    e.preventDefault();

    try {
      if (evaluacion) {
        await api.put(`/evaluaciones-psicopedagogicas/${evaluacion.id}/`, formData);
      } else {
        await api.post("/evaluaciones-psicopedagogicas/", formData);
      }

      alert("✔ Guardado correctamente");
      onSuccess();
      setFormData({
        estudiante: "",
        evaluador: "",
        fecha: "",
        observaciones: "",
      });
      setAlumnoSelected(null);
    } catch (error) {
      console.error(error);
      alert("❌ Error al guardar");
    }
  }

  // ===============================
  // HANDLE CHANGE DEL SELECT
  // ===============================
  const handleAlumnoChange = (e) => {
    const id = e.target.value;
    setFormData({ ...formData, estudiante: id });
    cargarFichaAlumno(id);
  };

  return (
    <form className="card p-3 shadow-sm" onSubmit={handleSubmit}>
      <h4 className="mb-3">Formulario de Evaluación Psicopedagógica</h4>

      {/* ==========================
          SELECT ALUMNO
      =========================== */}
      <div className="mb-3">
        <label className="form-label">Alumno</label>
        <select
          className="form-select"
          value={formData.estudiante}
          onChange={handleAlumnoChange}
          required
        >
          <option value="">Seleccionar alumno...</option>
          {alumnos.map((al) => (
            <option key={al.id} value={al.id}>
              {al.nombres_apellidos} — {al.curso?.nombre || "Sin curso"}
            </option>
          ))}
        </select>
      </div>

      {/* ==========================
          FICHA DEL ALUMNO
      =========================== */}
      {alumnoSelected && (
        <div className="alert alert-secondary">
          <h5>Ficha del Alumno</h5>
          <p><b>Nombre:</b> {alumnoSelected.nombres_apellidos}</p>
          <p><b>RUN:</b> {alumnoSelected.run || "—"}</p>
          <p><b>Curso:</b> {alumnoSelected.curso?.nombre || "—"}</p>
          <p><b>Género:</b> {alumnoSelected.genero || "—"}</p>
          <p><b>Nacimiento:</b> {alumnoSelected.fecha_nacimiento || "—"}</p>
          <p><b>Apoderado:</b> {alumnoSelected.apoderado?.nombres_apellidos || "—"}</p>
        </div>
      )}

      {/* ==========================
          EVALUADOR
      =========================== */}
      <div className="mb-3">
        <label className="form-label">Evaluador</label>
        <input
          type="text"
          className="form-control"
          value={formData.evaluador}
          onChange={(e) => setFormData({ ...formData, evaluador: e.target.value })}
          required
        />
      </div>

      {/* ==========================
          FECHA
      =========================== */}
      <div className="mb-3">
        <label className="form-label">Fecha</label>
        <input
          type="date"
          className="form-control"
          value={formData.fecha}
          onChange={(e) => setFormData({ ...formData, fecha: e.target.value })}
        />
      </div>

      {/* ==========================
          OBSERVACIONES
      =========================== */}
      <div className="mb-3">
        <label className="form-label">Observaciones</label>
        <textarea
          className="form-control"
          rows="3"
          value={formData.observaciones}
          onChange={(e) => setFormData({ ...formData, observaciones: e.target.value })}
        ></textarea>
      </div>

      <button className="btn btn-primary w-100">
        {evaluacion ? "Actualizar" : "Crear"}
      </button>
    </form>
  );
}

export default EvaluacionPsicoForm;
